CREATE TABLE command_activity_invocation (
          activity_id text primary key references command_activity(activity_id) on delete cascade,
          invocation_preview text not null check (
            length(invocation_preview) between 1 and 4096
          )
        )

CREATE TRIGGER trg_command_activity_delete_children
        after delete on command_activity
        begin
          delete from command_activity_correlations where activity_id = old.activity_id;
          delete from command_activity_matches where activity_id = old.activity_id;
        end

CREATE TRIGGER trg_guard_workflow_receipt_require_parents
    before insert on guard_workflow_capability_receipts
    begin
      select case when not exists (
        select 1 from guard_workflow_capabilities where capability_id = new.capability_id
      ) then raise(abort, 'workflow_capability_parent_missing') end;
      select case when not exists (
        select 1 from guard_events where event_id = new.event_id
      ) then raise(abort, 'workflow_capability_event_missing') end;
    end

CREATE TRIGGER trg_guard_workflow_transition_require_parents
    before insert on guard_workflow_capability_authority_transitions
    begin
      select case when not exists (
        select 1 from guard_workflow_capabilities where capability_id = new.capability_id
      ) then raise(abort, 'workflow_capability_transition_parent_missing') end;
      select case when new.event_id is not null and not exists (
        select 1 from guard_events where event_id = new.event_id
      ) then raise(abort, 'workflow_capability_transition_event_missing') end;
    end

CREATE TRIGGER trg_command_activity_shadow_require_evaluation
    before insert on command_activity_shadow_cohorts
    begin
      select case when not exists (
        select 1 from command_activity_shadow_evaluations where activity_id = new.activity_id
      ) then raise(abort, 'command_activity_shadow_evaluation_missing') end;
      select case when new.ordinal != (
        select count(*) from command_activity_shadow_cohorts where activity_id = new.activity_id
      ) then raise(abort, 'command_activity_shadow_cohort_ordinal_invalid') end;
    end
